"use client"

import type { ComponentProps as PlaygroundComponentProps } from "react"
import { Button } from "@/components/ui/button";

import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";

const playgroundProps: Partial<PlaygroundComponentProps<typeof Dialog>> = /*__DS_PROPS__*/ {}


export function DialogDemo() {
  return (
    <Dialog>{playgroundProps.children ?? <>
      <DialogTrigger asChild>
        <Button variant="outline">Open dialog</Button>
      </DialogTrigger>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Dialog title</DialogTitle>
          <DialogDescription>
            This is a dialog description for the design system preview.
          </DialogDescription>
        </DialogHeader>
      </DialogContent>
    </>}</Dialog>
  )
}

